package solution

import "errors"

type Condition struct { Type string; Active bool }
type Blueprint struct { Name string; Labels map[string]string }
type Workload struct { Name string; Labels map[string]string; Conditions []Condition }
type Result struct { Action string; Workload *Workload; Conditions []Condition }
func labelsCopy(x map[string]string) map[string]string { if x==nil{return nil}; y:=make(map[string]string,len(x));for k,v:=range x{y[k]=v};return y }
func labelsEqual(a,b map[string]string) bool { if len(a)!=len(b){return false};for k,v:=range a{if b[k]!=v{return false}};return true }
func workloadCopy(w *Workload) *Workload { if w==nil{return nil}; return &Workload{Name:w.Name,Labels:labelsCopy(w.Labels),Conditions:append([]Condition(nil),w.Conditions...)} }
func Reconcile(b Blueprint, current *Workload) (Result,error) {
	if b.Name=="" { c:=[]Condition{{"Invalid",true}};return Result{"error",nil,c},errors.New("empty name") }
	for k:=range b.Labels { if k=="" { c:=[]Condition{{"Invalid",true}};return Result{"error",nil,c},errors.New("empty label key") } }
	if current==nil { c:=[]Condition{{"Provisioning",true}}; w:=&Workload{Name:b.Name,Labels:labelsCopy(b.Labels),Conditions:append([]Condition(nil),c...)};return Result{"create",w,c},nil }
	if current.Labels["lifecycle"]=="remove" { c:=[]Condition{{"Removing",true}};return Result{"delete",nil,c},nil }
	if current.Name!=b.Name || !labelsEqual(current.Labels,b.Labels) { c:=[]Condition{{"Synchronizing",true}};w:=&Workload{Name:b.Name,Labels:labelsCopy(b.Labels),Conditions:append([]Condition(nil),c...)};return Result{"update",w,c},nil }
	w:=workloadCopy(current); c:=append([]Condition(nil),current.Conditions...);return Result{"none",w,c},nil
}
